public class StreamStatsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("sum of squares of evens", 20, StreamStats.sumOfSquaresOfEvens(java.util.List.of(1, 2, 3, 4)));
        check("no evens", 0, StreamStats.sumOfSquaresOfEvens(java.util.List.of(5, 7)));
        check("repeated evens", 44, StreamStats.sumOfSquaresOfEvens(java.util.List.of(2, 2, 6)));
        check("negative even", 16, StreamStats.sumOfSquaresOfEvens(java.util.List.of(-4, 3)));
        check("upperSorted basic", java.util.List.of("APPLE", "FIG", "PEAR"),
                StreamStats.upperSorted(java.util.List.of("pear", "apple", "fig")));
        java.util.List<String> input = new java.util.ArrayList<>(java.util.List.of("pear", "apple"));
        check("upperSorted returns new list", java.util.List.of("APPLE", "PEAR"), StreamStats.upperSorted(input));
        check("input list unchanged", "[pear, apple]", input.toString());
        check("upperSorted empty", java.util.List.of(), StreamStats.upperSorted(java.util.List.of()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

