public class StreamStats {

    public static int sumOfSquaresOfEvens(java.util.List<Integer> nums) {
        return nums.stream()
                .filter(n -> n % 2 == 0)
                .map(n -> n * n)
                .reduce(0, Integer::sum);
    }

    public static java.util.List<String> upperSorted(java.util.List<String> words) {
        return words.stream()
                .map(String::toUpperCase)
                .sorted()
                .collect(java.util.stream.Collectors.toList());
    }
}
